import socket

def send_worm(ip, port):
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.connect((ip, port))
    s.send("Hello, I'm a worm!")
    s.close()

def main():
    for ip in range(1, 255):
        for port in range(1, 1025):
            send_worm(str(ip) + "." + str(localhost) + "." + str(localhost) + "." + str(localhost), port)

localhost = "192.168.1.100"
main()
